<?php
require_once dirname(__DIR__).'/config.php';
$conn=db();
$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){$fineId=(int)($_POST['fine_id']??0);$amount=(float)($_POST['amount']??0);$method=$_POST['payment_method']??'CASH';$reference=trim($_POST['reference_number']??'');$remarks=trim($_POST['remarks']??'');if($fineId>0&&$amount>0){$s=$conn->prepare('INSERT INTO payments(fine_id,amount,payment_method,reference_number,remarks,recorded_by) VALUES(?,?,?,?,?,?)');$admin=(int)($_SESSION['admin_id']??0);$s->bind_param('idsssi',$fineId,$amount,$method,$reference,$remarks,$admin);if($s->execute()){$conn->query("UPDATE fines f SET status=CASE WHEN (SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.fine_id=f.id)>=f.amount THEN 'PAID' ELSE 'PARTIALLY PAID' END WHERE f.id=$fineId");$message='Payment recorded and fine balance updated.';}}}
$result=$conn->query("SELECT f.id,f.amount,f.status,f.reason,e.event_name,s.id student_id,s.student_no,s.first_name,s.last_name,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.fine_id=f.id),0) paid FROM fines f JOIN events e ON e.id=f.event_id JOIN students s ON s.id=f.student_id ORDER BY s.last_name,s.first_name,f.created_at DESC");$students=[];while($fine=$result->fetch_assoc()){$studentId=(int)$fine['student_id'];if(!isset($students[$studentId])){$students[$studentId]=['name'=>$fine['last_name'].', '.$fine['first_name'],'fines'=>[],'total_fine'=>0,'total_paid'=>0];}$students[$studentId]['fines'][]=$fine;$students[$studentId]['total_fine']+=(float)$fine['amount'];$students[$studentId]['total_paid']+=(float)$fine['paid'];}
$pageTitle='Fines & Payments';ob_start();?><div class="space-y-6"><?php if($message):?><div class="rounded-lg bg-emerald-100 p-3 text-emerald-800"><?php echo h($message);?></div><?php endif;?><div class="rounded-2xl bg-white p-5 shadow"><div class="mb-4 flex flex-wrap items-center justify-between gap-3"><div class="text-lg font-semibold">Payment management</div><label class="relative w-full sm:w-72"><span class="sr-only">Search student name</span><svg class="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="m21 19.6-4.2-4.2a7 7 0 1 0-1.4 1.4l4.2 4.2zM5 10a5 5 0 1 1 10 0A5 5 0 0 1 5 10"/></svg><input id="paymentStudentSearch" type="search" placeholder="Search student name" autocomplete="off" class="w-full rounded-lg border border-slate-300 py-2 pl-9 pr-3 text-sm outline-none transition focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100"></label></div><div class="overflow-x-auto"><table class="min-w-full text-sm"><thead><tr class="border-b text-left"><th class="px-2 py-2">Student / Events</th><th class="px-2 py-2">Fine</th><th class="px-2 py-2">Paid</th><th class="px-2 py-2">Balance</th><th class="px-2 py-2">Status</th><th class="px-2 py-2">Record payment</th></tr></thead><tbody id="paymentRows"><?php foreach($students as $student):$totalBalance=max(0,$student['total_fine']-$student['total_paid']);?><tr class="border-b align-top" data-student-name="<?php echo h($student['name']);?>"><td class="px-2 py-3"><div class="font-semibold text-slate-900"><?php echo h($student['name']);?></div><div class="mt-2 space-y-3"><?php foreach($student['fines'] as $fine):?><div class="border-l-2 border-indigo-200 pl-3 text-xs text-slate-600"><?php echo h($fine['event_name'].' - '.$fine['reason']);?></div><?php endforeach;?></div><div class="mt-3 border-t pt-2 text-xs font-semibold text-slate-700">TOTAL</div></td><td class="px-2 py-3"><div class="space-y-3"><?php foreach($student['fines'] as $fine):?><div>PHP <?php echo number_format($fine['amount'],2);?></div><?php endforeach;?></div><div class="mt-3 border-t pt-2 font-semibold">PHP <?php echo number_format($student['total_fine'],2);?></div></td><td class="px-2 py-3"><div class="space-y-3"><?php foreach($student['fines'] as $fine):?><div>PHP <?php echo number_format($fine['paid'],2);?></div><?php endforeach;?></div><div class="mt-3 border-t pt-2 font-semibold">PHP <?php echo number_format($student['total_paid'],2);?></div></td><td class="px-2 py-3"><div class="space-y-3"><?php foreach($student['fines'] as $fine):?><div class="font-semibold">PHP <?php echo number_format(max(0,(float)$fine['amount']-(float)$fine['paid']),2);?></div><?php endforeach;?></div><div class="mt-3 border-t pt-2 font-semibold">PHP <?php echo number_format($totalBalance,2);?></div></td><td class="px-2 py-3"><div class="space-y-3"><?php foreach($student['fines'] as $fine):?><div><?php echo h($fine['status']);?></div><?php endforeach;?></div><div class="mt-3 border-t pt-2 font-semibold">TOTAL</div></td><td class="px-2 py-3"><div class="space-y-3"><?php foreach($student['fines'] as $fine):$balance=(float)$fine['amount']-(float)$fine['paid'];?><div><?php if($balance>0):?><form method="post" class="grid min-w-52 gap-2"><input type="hidden" name="fine_id" value="<?php echo (int)$fine['id'];?>"><input name="amount" type="number" step="0.01" min="0.01" max="<?php echo h($balance);?>" placeholder="Amount" required class="rounded border px-2 py-1"><select name="payment_method" class="rounded border px-2 py-1"><option>CASH</option><option>GCASH</option><option>MAYA</option><option>BANK TRANSFER</option><option>OTHER</option></select><input name="reference_number" placeholder="Reference number" class="rounded border px-2 py-1"><input name="remarks" placeholder="Remarks" class="rounded border px-2 py-1"><button class="rounded bg-indigo-700 px-3 py-1 text-xs text-white">Record payment</button></form><?php else:?><span class="text-emerald-700">PAID</span><?php endif;?></div><?php endforeach;?></div><div class="mt-3 border-t pt-2 text-xs text-slate-500">Student total</div></td></tr><?php endforeach;?><tr id="paymentNoResults" class="hidden"><td colspan="6" class="px-2 py-8 text-center text-slate-500">No students found.</td></tr></tbody></table></div></div></div><script>document.getElementById('paymentStudentSearch').addEventListener('input',function(){var query=this.value.trim().toLowerCase(),rows=document.querySelectorAll('#paymentRows tr[data-student-name]'),matches=0;rows.forEach(function(row){var match=row.dataset.studentName.toLowerCase().indexOf(query)!==-1;row.classList.toggle('hidden',!match);if(match)matches++;});document.getElementById('paymentNoResults').classList.toggle('hidden',matches!==0);});</script><?php $content=ob_get_clean();include __DIR__.'/_layout.php';